                status?: string;
                /** @description Solo los contactos cuya `image` contenga este texto. */
                image?: string;
                /** @description Creados desde este momento (`AAAA-MM-DD` o ISO 8601); se ignora con `created_from` */
                created_at?: string;
                /** @description Inicio del rango de alta (`AAAA-MM-DD` o ISO 8601); va con `created_to` */
                created_from?: string;
