                            /** @description Cuándo se guardó el último mensaje (UTC). */
                            created_at?: string | null;
                            /** @description Cuándo cambió por última vez el último mensaje (UTC). */
                            updated_at?: string | null;
                            /** @description Lo que lo mandó, según `origin`: un flujo (`flw_`), una difusión (`bcs_`) o un agente de IA (`ast_`) */
                            origin_id?: string | null;
                            /** @description `uid` del mensaje al que responde */
