    "mac.status": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description OK */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description `false`: el control de contactos activos aún no está activo */
                        enforcement_enabled: boolean;
                        /** @description `true` si tu plan no limita contactos activos */
                        unlimited: boolean;
                        /** @description Siempre 0 en esta respuesta. */
                        current_count: number;
                        /** @description `null` con un plan ilimitado; si no, 0. */
                        limit: number | null;
                        /** @description `null` con un plan ilimitado; si no, 0. */
                        remaining: number | null;
                        /** @description Siempre 0 en esta respuesta. */
                        usage_percentage: number;
                        /**
                         * @description Siempre `normal` en esta respuesta.
                         * @enum {string}
                         */
                        state: "normal";
                        /** @description Siempre `null` en esta respuesta. */
                        grace: null;
                        /** @description Siempre `null` en esta respuesta. */
                        period_start: null;
                    } | {
                        /** @description Contactos activos usados en el ciclo */
                        mac_count: number;
                        /** @description Contactos activos del plan por ciclo */
                        mac_limit: number | null;
                        /** @description Capacidad del ciclo */
                        cycle_capacity: number | null;
                        /** @description Disponible además del plan */
                        accumulated_available: number | null;
                        /** @description Contactos activos que todavía puedes sumar */
                        total_available: number | null;
                        /** @description Porcentaje usado de `cycle_capacity` */
                        usage_percentage: number;
                        /** @description `true`: tu cuenta tiene activo el control de contactos activos. */
                        enforcement_enabled: boolean;
                        /**
                         * @description `warning_80` desde el 80 %, `limit_reached` desde el 100 %
                         * @enum {string|null}
                         */
                        alert_level: "warning_80" | "limit_reached" | null;
                        /** @description Saldos que vencen en 7 días */
                        expiring_buckets: {
                            /** @description Contactos activos que quedan en ese saldo. */
                            amount: number;
                            /** @description Días que faltan para que venza. */
                            expires_in_days: number;
                        }[];
                        /** @description Saldos vigentes, del que vence antes al que vence después */
                        buckets: {
                            /** @description De dónde viene el saldo */
                            source: string;
                            /** @description Contactos activos que quedan en ese saldo. */
                            macs_remaining: number;
                            /** @description Cuándo vence (UTC, `AAAA-MM-DD hh:mm:ss`). */
                            expires_at: string;
                        }[];
                        /**
                         * @description `normal`, `grace` (24 horas de gracia), `lockout`, bloqueo: terminaron las 24 horas sin que sumaras capacidad o `cleared`
                         * @enum {string}
                         */
                        state: "normal" | "grace" | "lockout" | "cleared";
                        /** @description Período de gracia o de bloqueo en curso, o el último */
                        grace: {
                            /** @description Número del período de gracia. */
                            grace_period_id: number | null;
                            /**
                             * Format: date-time
                             * @description Cuándo empezó la gracia (ISO 8601, UTC).
                             */
                            started_at: string | null;
                            /**
                             * Format: date-time
                             * @description Fin de las 24 horas de gracia
                             */
                            expires_at: string | null;
                            /** @description Segundos que le quedan a la gracia */
                            seconds_remaining: number;
                            /** @description Por qué terminó */
                            end_reason: string | null;
                        } | null;
                        /** @description `true` si tu plan no limita contactos activos */
                        unlimited: boolean;
                        /** @description Solo con workspaces de facturación propia */
                        workspace_id?: number;
                    };
                };
            };
            401: components["responses"]["ConversationsAuthenticationException"];
        };
    };
