    "apiGroupAction.sendMessage": {
        parameters: {
            query?: never;
            header?: never;
            path: {
                /**
                 * @description `uid` del grupo
                 * @example 120363041234567890
                 */
                group: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["SendGroupMessageRequest"];
            };
        };
        responses: {
            /** @description En cola */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["ApiGroupActionAcceptedResource"];
                };
            };
            401: components["responses"]["CommunitiesAuthenticationException"];
            /**
             * @description Tu clave no puede hacer esta llamada
             *
             *     - `permission_denied`: falta el permiso
             *     - `route_not_available`: no disponible para claves
             *     - `use_public_endpoint`: usa la dirección pública
             *     - `workspace_archived`: workspace archivado
             *     - `forbidden`: acción no permitida
             *     - `import_permission_required`: falta el permiso para importar
             */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description Código estable
                         * @enum {string}
                         */
                        error: "permission_denied" | "route_not_available" | "use_public_endpoint" | "workspace_archived" | "forbidden" | "import_permission_required";
                        /** @description Texto para personas */
                        message: string;
                    };
                };
            };
            /**
             * @description El número o el grupo no son tuyos
             *
             *     - `device_not_found`: el número no es de tu workspace
             *     - `group_not_found`: el grupo no es de tu workspace o el número no está
             */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description Código estable
                         * @enum {string}
                         */
                        error: "device_not_found" | "group_not_found";
                        /** @description Texto para personas */
                        message: string;
                    };
                };
            };
            /**
             * @description Ya se está importando; reintenta en segundos
             *
             *     - `import_in_progress`: otro pedido lo está importando
             */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description Código estable
                         * @enum {string}
                         */
                        error: "import_in_progress";
                        /** @description Texto para personas */
                        message: string;
                    };
                };
            };
            /**
             * @description Cuerpo inválido o envío no permitido; no salió nada
             *
             *     - `validation_failed`: mira `errors`
             *     - `device_not_connected`: conecta el número
             *     - `device_not_group_admin`: el número QR no administra el grupo
             *     - `device_not_group_number`: usa el número que creó el grupo
             *     - `unsupported_group_type`: comunidad o canal
             *     - `provider_unsupported`: el número no puede enviar aquí; mira `provider`
             *     - `window_closed`: oficial: ventana de 24 horas cerrada
             *     - `number_restricted`: oficial: la calidad del número no permite enviar
             *     - `unsupported_type`: oficial: ese `type` no se puede enviar
             */
            422: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description Código estable
                         * @enum {string}
                         */
                        error: "validation_failed" | "device_not_connected" | "device_not_group_admin" | "device_not_group_number" | "unsupported_group_type" | "provider_unsupported" | "window_closed" | "number_restricted" | "unsupported_type";
                        /** @description Texto para personas */
                        message: string;
                        /** @description Mensajes por campo */
                        errors?: Record<string, unknown>;
                        /** @description Tipo de número */
                        provider?: string;
                    };
                };
            };
            /**
             * @description Demasiados pedidos; espera `Retry-After`
             *
             *     - `too_many_pending_actions`: espera a que terminen las abiertas
             *     - `import_rate_limited`: 5 importaciones por minuto; mira `retry_after`
             *     - `rate_limited`: espera `Retry-After`
             *     - `daily_cap_exceeded`: tope diario de tu clave
             */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description Código estable
                         * @enum {string}
                         */
                        error: "too_many_pending_actions" | "import_rate_limited" | "rate_limited" | "daily_cap_exceeded";
                        /** @description Texto para personas */
                        message: string;
                        /** @description Segundos para volver a importar */
                        retry_after?: number;
                    };
                };
            };
            /**
             * @description WhatsApp no respondió al importar; no salió nada
             *
             *     - `provider_error`: WhatsApp falló; reintenta
             */
            502: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /**
                         * @description Código estable
                         * @enum {string}
                         */
                        error: "provider_error";
                        /** @description Texto para personas */
                        message: string;
                    };
                };
            };
        };
    };
